def maxProduct(nums):
    max_p = float('-inf')
    for i in range(len(nums)):
        for j in range(i, len(nums)):
            prod = 1
            for k in range(i, j + 1):
                prod *= nums[k]
            if prod > max_p:
                max_p = prod
    return max_p

